<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>راستا — هر قدم، نزدیک‌تر به هدف</title><script>(()=>{const t=localStorage.getItem('rasta-theme')||'system';const dark=t==='dark'||(t==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.classList.toggle('dark',dark);document.documentElement.dataset.theme=t})()</script>@vite(['resources/css/app.css','resources/js/app.js'])</head>
<body><div x-data="workspace" class="app-shell" x-cloak>
<div class="sidebar-backdrop" x-show="sidebar" x-transition.opacity.duration.150ms @click="sidebar=false"></div>
<aside class="sidebar" :class="{'is-open':sidebar}">
 <a href="/dashboard" @click.prevent="go('dashboard')" class="brand"><span class="brand-symbol"><span></span><span></span><span></span></span><strong>راستا<span>فضای کار تیمی</span></strong></a>
 <nav aria-label="ناوبری اصلی"><a href="/dashboard" @click.prevent="go('dashboard')" :class="{'active':page==='dashboard'}"><span x-html="$icon('House')"></span>خانه</a><a href="/tasks" @click.prevent="go('tasks')" :class="{'active':page==='tasks'}"><span x-html="$icon('CheckCheck')"></span>تسک‌های من<span class="nav-count" x-text="fa(myTasks.filter(t=>!t.completed_at).length)"></span></a><a href="/labels" @click.prevent="go('labels')" :class="{'active':page==='labels'}"><span x-html="$icon('Tags')"></span>برچسب‌ها</a></nav>
 <div class="sidebar-projects"><div class="eyebrow">پروژه‌های شما <button class="icon-btn" @click="openProject()" aria-label="پروژه جدید" x-html="$icon('Plus')"></button></div><template x-for="p in projects" :key="p.id"><button class="project-shortcut" @click="go('projects',p.id)"><i :style="`background:${p.color}`"></i><span x-text="p.name"></span></button></template></div>
 <div class="sidebar-bottom"><button class="user-account" @click="go('settings')"><span class="avatar"><img x-show="user.avatar_url" :src="user.avatar_url" :alt="user.name"><span x-show="!user.avatar_url" :style="`background:${color(user.id)}`" x-text="initials(user.name)"></span></span><span><strong x-text="user.name"></strong><small x-text="user.job_title"></small></span><span x-html="$icon('ChevronLeft')"></span></button></div>
</aside>
<div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" @click="sidebar=!sidebar" aria-label="باز کردن منو" x-html="$icon('Menu')"></button><span>فضای کار</span><span x-html="$icon('ChevronLeft')"></span><strong x-text="({dashboard:'خانه',projects:'پروژه‌ها',tasks:'تسک‌های من',labels:'برچسب‌ها',settings:'تنظیمات'})[page]"></strong><template x-if="currentProject"><span class="crumb-project"><span x-html="$icon('ChevronLeft')"></span><span x-text="currentProject.name"></span></span></template></div><div class="top-actions"><div class="notification-wrap" @click.outside="notificationsOpen=false"><button class="icon-btn notification-button" @click="notificationsOpen=!notificationsOpen" aria-label="اعلان‌ها"><span x-html="$icon('Bell')"></span><i x-show="unread"></i></button><div class="notification-panel" x-show="notificationsOpen" x-transition.opacity.scale.95.duration.150ms><div class="section-heading"><strong>اعلان‌ها</strong><button class="text-button" @click="readNotices()">خواندن همه</button></div><template x-for="n in notices" :key="n.id"><button :class="{'unread':!n.read_at}" @click="openTask(tasks.find(t=>t.id===n.task_id));notificationsOpen=false"><span x-text="n.body"></span><small x-text="commentTime(n.created_at)"></small></button></template><p class="muted" x-show="!notices.length&&!deadlines.length">همه چیز به‌روز است.</p><div class="notice-upcoming" x-show="deadlines.length"><strong>مهلت‌های نزدیک</strong><template x-for="t in deadlines.slice(0,3)" :key="t.id"><button @click="openTask(t);notificationsOpen=false"><span x-text="t.title"></span><small x-text="date(t.due_date)"></small></button></template></div></div></div><button class="avatar small top-avatar" @click="go('settings')" aria-label="حساب کاربری"><img x-show="user.avatar_url" :src="user.avatar_url" :alt="user.name"><span x-show="!user.avatar_url" :style="`background:${color(user.id)}`" x-text="initials(user.name)"></span></button></div></header>
<main class="content"><div x-show="loading" class="skeleton-wrap"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div><div x-show="loadError" class="error-banner"><span x-text="loadError"></span><button class="button" @click="refresh()">تلاش دوباره</button></div><div x-show="!loading&&!loadError">
@include('partials.dashboard')
@include('partials.projects')
@include('partials.tasks')
@include('partials.labels-settings')
</div></main><footer class="app-footer"><span class="status-dot"></span>فضایی برای تمرکز، مسیری برای رسیدن.<span>ساخته‌شده برای کار تیمی</span></footer></div>
@include('partials.modals')
<div class="confirm-backdrop" x-show="confirmBox" x-cloak x-transition.opacity.duration.150ms @keydown.escape.stop="confirmBox=null"><section class="confirm-dialog" x-show="confirmBox" x-transition.opacity.scale.95.duration.150ms role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><h2 id="confirm-title" x-text="confirmBox?.title"></h2><p x-text="confirmBox?.body"></p><label class="confirm-transfer" x-show="confirmBox?.transferOptions?.length">انتقال تسک‌ها به<select x-model.number="confirmBox.transferId"><template x-for="option in confirmBox.transferOptions" :key="option.id"><option :value="option.id" x-text="option.title"></option></template></select></label><div class="button-row"><button class="button danger" @click="confirm()" x-text="confirmBox?.label"></button><button class="button" @click="confirmBox=null">انصراف</button></div></section></div>
<div class="toast" x-show="toast" x-transition :class="{'toast-error':toastError}" role="status"><span x-html="$icon(toastError?'X':'CheckCircle2')"></span><span x-text="toast"></span><button class="icon-btn" @click="toast=''" aria-label="بستن پیام" x-html="$icon('X')"></button></div>
</div></body></html>
